-- Russian translations for all 12 news articles
INSERT INTO news (slug, lang, category, cat_label, cat_color, source, date, title, summary, body, published) VALUES

('claude-opus-47-swe-bench', 'ru', 'models', 'Модели', '#7c6af7', 'Anthropic Blog', '2026-04-17',
'Claude Opus 4.7 установил рекорд на SWE-bench: 87,6%',
'Claude Opus 4.7 от Anthropic установил новый рекорд на SWE-bench Verified — 87,6%, что является наивысшим результатом среди публично доступных моделей. По цене $5/$25 за миллион токенов модель знаменует качественный скачок в возможностях агентной разработки ПО.',
'<p>Новая флагманская модель Anthropic — <strong>Claude Opus 4.7</strong> — установила рекорд в отрасли на SWE-bench Verified, золотом стандарте для оценки ИИ в разработке программного обеспечения. Результат составил <strong>87,6%</strong> — выше всех ранее опубликованных показателей для публично доступных моделей.</p>
<h2>Что измеряет SWE-bench</h2>
<p>SWE-bench Verified проверяет, способен ли ИИ решать реальные задачи из GitHub-репозиториев популярных open-source проектов. Каждое задание требует от модели прочитать описание бага, разобраться в кодовой базе, написать исправление и пройти существующие тесты — без помощи человека.</p>
<h2>Цены и доступность</h2>
<p>Claude Opus 4.7 стоит <strong>$5 за миллион входящих токенов и $25 за миллион исходящих</strong> — позиционируется как премиальный вариант для команд, создающих агентные рабочие процессы. Доступна через Anthropic API и Claude.ai Pro.</p>
<h3>Что это значит для разработчиков</h3>
<p>Результат сигнализирует о качественном сдвиге в том, что ИИ-агенты могут делать автономно. При 87,6% модель способна надёжно исправлять большинство реальных багов без вмешательства человека — возможность, которая ещё 18 месяцев назад считалась недостижимой.</p>
<p>Anthropic описывает Claude Opus 4.7 как модель, созданную специально для долгосрочных агентных задач: многошаговых проектов по разработке, автоматизированных тестовых конвейеров и сложных рефакторингов, которые раньше требовали опытных инженеров.</p>',
true),

('gpt-54-three-variants-1m-context', 'ru', 'models', 'Модели', '#7c6af7', 'OpenAI Blog', '2026-04-16',
'GPT-5.4 вышел в трёх вариантах с контекстом 1 млн токенов',
'OpenAI выпустила GPT-5.4 в вариантах Standard, Thinking и Pro. Все три версии имеют контекстное окно в 1,05 миллиона токенов — наибольшее в коммерческих предложениях OpenAI. Модель динамически загружает спецификации инструментов вместо их предварительной загрузки.',
'<p>OpenAI расширила линейку моделей, выпустив <strong>GPT-5.4</strong> в трёх вариантах: Standard, Thinking и Pro. Все три версии имеют единую архитектуру и <strong>контекстное окно в 1,05 миллиона токенов</strong> — наибольшее из всех коммерческих предложений OpenAI.</p>
<h2>Три варианта</h2>
<p><strong>Standard</strong> оптимизирован для скорости и стоимости, подходит для большинства повседневных задач. <strong>Thinking</strong> добавляет расширенный слой рассуждений для сложных задач. <strong>Pro</strong> сочетает максимальные возможности с наибольшим контекстным окном для самых требовательных случаев использования.</p>
<h2>Динамическая загрузка инструментов</h2>
<p>Важное архитектурное изменение в GPT-5.4 — динамическая загрузка спецификаций инструментов. Вместо загрузки всех определений инструментов в начале каждого разговора, модель запрашивает только нужные спецификации по мере возникновения задач. Это снижает объём промпта и улучшает качество ответов в сложных агентных рабочих процессах.</p>
<h3>Доступность</h3>
<p>GPT-5.4 Standard сразу доступен подписчикам ChatGPT Plus. Варианты Thinking и Pro доступны через API и для клиентов ChatGPT Team и Enterprise.</p>',
true),

('apple-rebuilds-siri-google-gemini', 'ru', 'business', 'Бизнес', '#f5a623', '9to5Mac', '2026-04-16',
'Apple переписала Siri на базе Google Gemini через приватное облако',
'Apple анонсировала полностью переработанную Siri на основе модели Gemini от Google, работающей в инфраструктуре Private Cloud Compute от Apple. Новая Siri впервые выполняет многошаговые задачи на устройстве и отвечает на сложные вопросы с значительно большей точностью.',
'<p>Apple объявила о полном переосмыслении Siri на базе <strong>модели Gemini от Google</strong>, работающей в инфраструктуре Private Cloud Compute Apple. Это самое значительное изменение Siri с момента её появления в 2011 году.</p>
<h2>Private Cloud Compute</h2>
<p>Новая Siri обрабатывает сложные запросы в облаке, сохраняя при этом гарантии конфиденциальности Apple. Архитектура Private Cloud Compute обеспечивает обработку запросов на серверах под управлением Apple с аппаратной аттестацией — это означает, что даже сотрудники Apple не могут получить доступ к данным пользователей.</p>
<h2>Возможности новой Siri</h2>
<p>Переработанная Siri впервые выполняет <strong>многошаговые задачи на устройстве</strong> — комбинируя действия в нескольких приложениях без отправки данных на внешние серверы. Для более сложных запросов, требующих передовых возможностей, она обращается к Gemini через Private Cloud Compute.</p>
<h3>Почему Google, а не OpenAI?</h3>
<p>Ранее Apple сотрудничала с OpenAI для интеграции ChatGPT в Apple Intelligence 1.0. Переход на Gemini, по имеющимся данным, объясняется как преимуществами в производительности, так и более глубокими коммерческими отношениями между Apple и Google, которая уже платит Apple миллиарды долларов ежегодно за размещение поиска по умолчанию.</p>
<p>Новая Siri ожидается в составе iOS 20 в этом году.</p>',
true),

('stanford-ai-index-2026', 'ru', 'research', 'Исследования', '#4aaef5', 'Stanford HAI', '2026-04-15',
'Индекс ИИ Стэнфорда 2026: ИИ принимают быстрее, чем ПК или интернет',
'Ежегодный Индекс ИИ Стэнфорда показывает, что по состоянию на март 2026 года Anthropic возглавляет общий рейтинг моделей, немного опережая xAI, Google и OpenAI. Люди принимают ИИ быстрее, чем в своё время принимали персональный компьютер или интернет.',
'<p>Институт человекоцентричного ИИ Стэнфордского университета опубликовал ежегодный <strong>Индекс ИИ 2026</strong> — наиболее полный обзор прогресса, распространения и социального влияния искусственного интеллекта.</p>
<h2>Anthropic возглавляет общий рейтинг</h2>
<p>Впервые <strong>Anthropic</strong> возглавила общий рейтинг производительности моделей по версии Стэнфорда, незначительно опередив xAI, Google и OpenAI. Рейтинг агрегирует показатели по рассуждениям, кодированию, науке и языковым тестам.</p>
<h2>Распространение опережает все предыдущие технологии</h2>
<p>Наиболее впечатляющий вывод доклада — темп распространения. ИИ-инструменты достигли <strong>500 миллионов постоянных пользователей быстрее, чем персональный компьютер, интернет или смартфон</strong>. Авторы объясняют это нулевым порогом доступа — в отличие от предыдущих технологических волн, ИИ не требует покупки оборудования или технической настройки.</p>
<h3>Ключевые показатели доклада</h3>
<p>По данным начала 2026 года, 67% работников умственного труда используют ИИ-инструменты не реже одного раза в неделю. Код с участием ИИ составляет около 35% всего нового кода в публичных репозиториях. Инвестиции в ИИ-инфраструктуру в 2025 году составили $420 миллиардов — более чем вдвое больше показателя 2023 года.</p>
<p>Полный доклад доступен на hai.stanford.edu.</p>',
true),

('pwc-top-companies-ai-economic-gains', 'ru', 'research', 'Исследования', '#4aaef5', 'PwC', '2026-04-14',
'PwC: топ-20% компаний получают 75% экономической выгоды от ИИ',
'Исследование PwC по эффективности ИИ 2026 года фиксирует острый разрыв: небольшая группа компаний, сфокусированных на росте, а не только на производительности, вырывается далеко вперёд. В докладе предупреждают, что большинство бизнесов всё ещё в режиме экспериментов и упускают накопительную отдачу.',
'<p>Исследование PwC по эффективности ИИ 2026 года, основанное на данных 5 000 компаний из 22 отраслей, выявляет растущий разрыв между лидерами в области ИИ и остальным рынком.</p>
<h2>Разрыв 20/75</h2>
<p>Топ-20% компаний — те, кого PwC называет «AI Frontier» — получают <strong>75% экономической ценности, создаваемой ИИ</strong>. Ключевое отличие — не объём технологических инвестиций или доступ к моделям, а стратегическая ориентация: компании-лидеры используют ИИ для <strong>создания новых источников дохода</strong>, а не только для сокращения затрат.</p>
<h2>Что отличает лидеров от аутсайдеров</h2>
<p>В докладе выявлены три общие характеристики компаний AI Frontier: наличие топ-менеджера, ответственного за результаты ИИ; измерение влияния ИИ в показателях выручки, а не эффективности; перестройка хотя бы одного ключевого бизнес-процесса вокруг возможностей ИИ.</p>
<h3>Опасность режима экспериментов</h3>
<p>PwC предупреждает, что 60% компаний всё ещё находятся в режиме экспериментов — запускают пилоты без масштабирования до рабочего продакшена. Компании в этой фазе не только упускают накопительную отдачу, но и всё больше отстают, пока лидеры наращивают преимущества в данных.</p>',
true),

('openai-acquires-tbpn', 'ru', 'business', 'Бизнес', '#f5a623', 'The Verge', '2026-04-14',
'OpenAI приобрела медиашоу Кремниевой долины TBPN',
'OpenAI объявила о приобретении TBPN, Technology Business Programming Network — ежедневного живого технологического и бизнес-шоу, ставшего культовым явлением в Кремниевой долине. Это первое приобретение медиакомпании в истории OpenAI.',
'<p>OpenAI приобрела <strong>TBPN (Technology Business Programming Network)</strong> — ежедневное стриминговое шоу о технологиях, ИИ и бизнесе, ставшее одной из самых популярных программ Кремниевой долины за последние два года.</p>
<h2>Что такое TBPN?</h2>
<p>TBPN выходит в прямом эфире по будням и транслирует интервью с основателями, инвесторами и технологами. Шоу приобрело репутацию откровенных, незаскриптованных разговоров в то время, когда большинство технологических СМИ переключились на монтированный видеоконтент. У шоу сложилась лояльная аудитория среди основателей стартапов и венчурных капиталистов.</p>
<h2>Первое медиаприобретение OpenAI</h2>
<p>Это <strong>первое приобретение медиакомпании</strong> в истории OpenAI, означающее стратегическое расширение за пределы разработки ИИ-моделей. Шаг сигнализирует об амбициях OpenAI по выстраиванию прямых отношений с аудиторией и формированию нарратива вокруг разработки ИИ.</p>
<h3>Редакционная независимость</h3>
<p>OpenAI заявила, что TBPN продолжит работу независимо с существующей командой. Компания утверждает, что не будет осуществлять редакционный контроль над контентом. Отраслевые наблюдатели скептически оценивают, насколько реальной может быть эта независимость под корпоративным владением.</p>
<p>Финансовые условия сделки не раскрываются.</p>',
true),

('anthropic-confirms-claude-mythos', 'ru', 'models', 'Модели', '#7c6af7', 'Anthropic Blog', '2026-04-13',
'Anthropic подтвердила существование Claude Mythos — но не выпустит его публично',
'Anthropic подтвердила существование Claude Mythos — по описанию, наиболее мощной модели, которую компания когда-либо создавала. Публичного релиза не планируется. Доступ ограничен примерно 50 партнёрскими организациями через проект Glasswing, сосредоточенный на кибербезопасности и сложных рассуждениях.',
'<p>Anthropic официально подтвердила существование <strong>Claude Mythos</strong> — модели, которую компания описывает как наиболее мощную из когда-либо созданных, и которую она не планирует выпускать в открытый доступ.</p>
<h2>Проект Glasswing</h2>
<p>Доступ к Claude Mythos управляется через <strong>проект Glasswing</strong> — закрытую программу для примерно 50 партнёрских организаций. Партнёры в основном сосредоточены в двух областях: продвинутые исследования в сфере кибербезопасности и сложные многошаговые задачи рассуждения, выходящие за пределы возможностей публично доступных моделей.</p>
<h2>Почему не выпускают?</h2>
<p>Генеральный директор Anthropic Дарио Амодеи заявил, что возможности Mythos в определённых областях — в частности, автономные действия и убеждение — пересекают пороги, требующие контролируемого развёртывания. Компания использует опыт Glasswing для разработки протоколов безопасности перед любым более широким выпуском.</p>
<h3>Что известно о возможностях</h3>
<p>Anthropic не публиковала результаты тестов для Mythos. Партнёрские организации описывают модель как способную к устойчивой автономной работе в рамках сложных многодневных задач. Один из партнёров в области кибербезопасности описал её как способную проводить сквозное тестирование на проникновение с минимальным участием человека.</p>',
true),

('openai-25b-revenue-ipo-2026', 'ru', 'business', 'Бизнес', '#f5a623', 'Bloomberg', '2026-04-13',
'OpenAI превысила $25 млрд годовой выручки и готовится к IPO в 2026',
'OpenAI превысила $25 миллиардов годовой выручки и, по имеющимся данным, делает первые шаги к публичному размещению — возможно, уже в конце 2026 года. Anthropic отстаёт совсем немного — около $19 миллиардов годовой выручки.',
'<p>OpenAI превысила отметку в <strong>$25 миллиардов годовой выручки</strong> по данным источников, знакомых с финансовыми показателями компании, и предпринимает первые шаги к первичному публичному размещению акций, возможно, в конце 2026 года.</p>
<h2>Структура выручки</h2>
<p>Основная часть выручки OpenAI приходится на подписки ChatGPT и использование API. Корпоративные контракты — включая крупные внедрения в компаниях из списка Fortune 500 — являются самым быстрорастущим сегментом и составляют около 40% общей выручки.</p>
<h2>Anthropic близко следом</h2>
<p><strong>Anthropic приближается к $19 миллиардам</strong> годовой выручки благодаря высокому корпоративному спросу на Claude и его интеграции в Amazon Web Services через платформу Bedrock. Разрыв между двумя компаниями значительно сократился за последние 12 месяцев.</p>
<h3>Сроки IPO</h3>
<p>Путь OpenAI к публичному размещению осложнялся необычной структурой ограниченной прибыли. В начале 2026 года компания завершила реструктуризацию, преобразовавшись в более традиционную корпорацию с общественной выгодой, устранив ключевое препятствие для IPO. По имеющимся данным, банкиры Goldman Sachs и Morgan Stanley ведут предварительные переговоры с компанией.</p>',
true),

('meta-llama-4-scout-10m-context', 'ru', 'models', 'Модели', '#7c6af7', 'Meta AI Blog', '2026-04-12',
'Meta Llama 4 Scout: контекст 10 млн токенов с архитектурой MoE',
'Meta выпустила Llama 4 Scout и Maverick — первые модели в семействе Llama с архитектурой Mixture-of-Experts. Scout имеет 17 млрд активных параметров на 16 экспертов (109 млрд всего) и контекстное окно в 10 миллионов токенов. Доступны для коммерческого использования.',
'<p>Meta выпустила <strong>Llama 4 Scout и Maverick</strong> — первые модели в семействе Llama, использующие <strong>архитектуру Mixture-of-Experts (MoE)</strong>, которая активирует лишь часть параметров для каждого запроса, значительно повышая эффективность.</p>
<h2>Scout: создан для длинного контекста</h2>
<p>Llama 4 Scout имеет <strong>17 миллиардов активных параметров</strong> на 16 экспертов (109 миллиардов параметров всего) и <strong>контекстное окно в 10 миллионов токенов</strong> — наибольшее среди открытых моделей. Это позволяет Scout обрабатывать целые кодовые базы, юридические документы или исследовательские архивы за один проход.</p>
<h2>Maverick: создан для производительности</h2>
<p>Llama 4 Maverick — вариант с более высокими возможностями, большим числом экспертов и лучшими показателями в тестах по рассуждениям и программированию. Meta позиционирует его как конкурентоспособный с закрытыми фронтирными моделями по большинству стандартных оценок.</p>
<h3>Коммерческое использование</h3>
<p>Обе модели доступны для коммерческого использования по обновлённой лицензии Llama от Meta, которая снимает прежние ограничения для компаний с большой пользовательской базой. Веса можно скачать с Hugging Face и запустить на стандартном GPU-оборудовании.</p>
<p>По данным Meta, архитектура MoE снижает стоимость инференса примерно на 60% по сравнению с полносвязной моделью аналогичного качества — значительное преимущество для крупномасштабных развёртываний.</p>',
true),

('google-gemma-4-31b-open-model', 'ru', 'models', 'Модели', '#7c6af7', 'Google Blog', '2026-04-10',
'Google выпустила Gemma 4: открытая модель 31B занимает 3-е место в мире',
'Google выпустила Gemma 4 в четырёх вариантах от 2,3 до 31 миллиарда параметров. Модель 31B Dense занимает 3-е место в мировом рейтинге Arena AI среди открытых моделей — это сильнейшая открытая модель Google на сегодняшний день.',
'<p>Google выпустила <strong>Gemma 4</strong> — последнее поколение семейства открытых моделей — в четырёх вариантах от <strong>2,3 до 31 миллиарда параметров</strong>.</p>
<h2>Gemma 4 31B: №3 в мире</h2>
<p>Флагманская <strong>Gemma 4 31B Dense занимает третье место в мировом рейтинге</strong> Arena AI среди открытых моделей — уступая только значительно более крупным моделям. Это делает её сильнейшей открытой моделью, когда-либо выпущенной Google, и серьёзным конкурентом семейству Llama от Meta.</p>
<h2>Варианты моделей</h2>
<p>Четыре варианта Gemma 4 — 2,3B, 7B, 14B и 31B — разработаны для различных сценариев развёртывания: от мобильных приложений на устройстве до облачного инференса. Все варианты поддерживают контекстное окно в 128K токенов и оптимизированы для TPU-оборудования Google, а также стандартных видеокарт NVIDIA.</p>
<h3>Мультимодальные возможности</h3>
<p>Впервые в серии Gemma варианты 14B и 31B включают нативные возможности работы с изображениями, позволяя обрабатывать изображения наряду с текстом. Это приближает Gemma к паритету функциональности с закрытыми мультимодальными моделями.</p>
<p>Все веса Gemma 4 доступны на Hugging Face и Google AI Studio под открытой лицензией, допускающей коммерческое использование.</p>',
true),

('eu-ai-act-full-enforcement', 'ru', 'regulation', 'Регулирование', '#f56565', 'Wired', '2026-04-09',
'Закон ЕС об ИИ вступил в полную силу: крупные провайдеры публикуют документы о соответствии',
'Закон ЕС об ИИ вступил в полную силу в марте 2026 года, обязав все ИИ-системы в ЕС соответствовать требованиям прозрачности, безопасности и классификации рисков. OpenAI, Anthropic и Google опубликовали документацию о соответствии GPAI.',
'<p>Закон ЕС об ИИ вступил в <strong>полную силу в марте 2026 года</strong>, завершив поэтапный период внедрения, начавшийся с принятия Закона в 2024 году. Регулирование теперь распространяется на все ИИ-системы, развёртываемые в ЕС, вне зависимости от местонахождения разработчика.</p>
<h2>Требования Закона</h2>
<p>Закон об ИИ устанавливает основанную на оценке рисков систему. <strong>Высокорисковые системы</strong> — применяемые в найме, кредитном скоринге, здравоохранении, правоохранительной деятельности и критической инфраструктуре — должны пройти официальные оценки соответствия, зарегистрироваться в центральной базе данных ЕС и обеспечить постоянный мониторинг.</p>
<h2>Соответствие для ИИ общего назначения</h2>
<p>Для крупных провайдеров базовых моделей вступили в силу новые <strong>обязательства GPAI (General Purpose AI)</strong>. OpenAI, Anthropic, Google и Mistral опубликовали свою документацию о соответствии, охватывающую прозрачность обучающих данных, раскрытие информации об авторских правах и результаты состязательного тестирования.</p>
<h3>Санкции</h3>
<p>Нарушения Закона об ИИ могут повлечь штрафы в размере до <strong>35 миллионов евро или 7% годового мирового оборота</strong> — в зависимости от того, что больше. Недавно созданное Европейское ведомство по ИИ со штаб-квартирой в Брюсселе отвечает за правоприменение и уже начало предварительные расследования в отношении ряда компаний.</p>
<p>За регулированием внимательно следят законодатели США, Великобритании и Азии — как за возможным шаблоном для национальных систем управления ИИ.</p>',
true),

('zhipu-glm-51-744b-open-source', 'ru', 'models', 'Модели', '#7c6af7', 'Zhipu AI Blog', '2026-04-08',
'Zhipu AI открыла исходный код GLM-5.1: модель MoE с 744 млрд параметров',
'Китайская лаборатория Zhipu AI выпустила GLM-5.1 под лицензией MIT — модель mixture-of-experts с 744 миллиардами параметров, 40 миллиардами активных параметров за проход и контекстным окном в 200K токенов. Полностью открытый выпуск создаёт серьёзное давление на конкурентов с закрытым кодом.',
'<p>Китайская ИИ-лаборатория Zhipu AI выпустила <strong>GLM-5.1</strong> под лицензией MIT — одной из наиболее разрешительных лицензий с открытым исходным кодом — что делает её свободной для любого использования, включая коммерческое развёртывание без ограничений.</p>
<h2>Масштаб и архитектура</h2>
<p>GLM-5.1 — это <strong>модель Mixture-of-Experts с 744 миллиардами параметров</strong> и 40 миллиардами активных параметров за один прямой проход. Такая архитектура обеспечивает производительность, сравнимую со значительно более крупными полносвязными моделями, при управляемых затратах на инференс. Модель поддерживает <strong>контекстное окно в 200 000 токенов</strong>.</p>
<h2>Результаты тестов</h2>
<p>По стандартным оценкам, включая MMLU, HumanEval и MATH, GLM-5.1 соответствует или превосходит производительность GPT-4 в большинстве категорий. Кодирование и математические рассуждения заявлены как особые сильные стороны: по тестам по соревновательному программированию модель набирает выше 85%.</p>
<h3>Почему это важно</h3>
<p>Полностью открытый выпуск под лицензией MIT значителен тем, что не накладывает никаких ограничений на использование, модификацию или распространение модели. Предыдущие крупные открытые модели, включая семейство Llama от Meta, имеют кастомные лицензии с различными ограничениями. Лицензия MIT для GLM-5.1 делает её наиболее свободно доступной фронтирной моделью на сегодняшний день.</p>
<p>Веса доступны для скачивания на Hugging Face. Zhipu AI также управляет коммерческим API для команд, предпочитающих управляемый инференс.</p>',
true);
